"""Additional authored tasks and finite, materialised parameter families.
Family members are explicit in the shipped JSON and individually checked.
"""
from bank_tools import *
Q={t['id']:t for t in bank}
def add(tid,prompt,answer,solution,oracle,family=None,options=None):
    t=Q[tid];n=len(t['tasks'])+1
    val,display=answer if isinstance(answer,tuple) else (answer,str(answer))
    q=dict(id=f'{tid}-{n}',prompt=prompt,answer=val,display=display,solution=solution,kind='set' if isinstance(val,list) else 'number',difficulty='Практика')
    if family:q['family']=family
    if options:q.update(options)
    t['tasks'].append(q);ORACLES[q['id']]=oracle
